"""Toolbar/window PNG icons embedded as base64.

Avoids listing/copying ``resource/icon`` during ``colcon build`` / pip install.
Regenerate after changing these PNGs (see comment at bottom).
"""

from __future__ import annotations

import base64

from PyQt5.QtCore import QByteArray
from PyQt5.QtGui import QIcon, QPixmap

_EMBEDDED_PNG_B64: dict[str, str] = {
    'logo0.png': '',
    'logo2.png': '',
    'logo3.png': '',
    'logo4.png': '',
    'logo5.png': '',
}


def qicon_from_embedded(name: str) -> QIcon | None:
    """Return a :class:`QIcon` for known toolbar names, or ``None`` if not embedded."""
    b64 = _EMBEDDED_PNG_B64.get(name)
    if not b64:
        return None
    data = base64.b64decode(b64.encode('ascii'))
    pix = QPixmap()
    if not pix.loadFromData(QByteArray(data), "PNG"):
        return None
    return QIcon(pix)

# Regenerate:
#   python3 phd/script/embed_toolbar_icons.py   (if you add this helper script)
